const dictionaries: Record<AppLanguage, Record<TranslationKey, string>> = { en, hu }

export type Translate = (key: TranslationKey, variables?: Record<string, string | number>) => string

export function getTranslator(language: AppLanguage): Translate {
  const dictionary = dictionaries[language]
  return (key, variables = {}) => Object.entries(variables).reduce(
    (text, [name, value]) => text.replaceAll(`{${name}}`, String(value)),
    dictionary[key]
  )
}

export function localeFor(language: AppLanguage): string {
  return language === 'hu' ? 'hu-HU' : 'en-US'
}
